                    </p>
                  </div>
                </div>
              )}
            </div>
            {/* BACKEND PLACEHOLDER END */}

            <div className="mt-4 flex justify-end">
              <button
                type="button"
                onClick={onScan}
                disabled={isScanning}
                className="inline-flex items-center gap-2 rounded-full bg-green-600 px-5 py-2 text-sm font-semibold text-white shadow-lg shadow-green-600/30 transition-colors hover:bg-green-700 disabled:cursor-not-allowed disabled:bg-green-300 disabled:shadow-none"
              >
                <FontAwesomeIcon icon={faCamera} />
                {isScanning ? "Scanning..." : "Scan"}
              </button>
            </div>
          </div>

          <ScannerTips />
        </div>
      </section>
    </main>
  );
}

export default function ScannerPage() {
  const galleryInputRef = useRef<HTMLInputElement | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [scanResult, setScanResult] = useState<string | null>(null);
  const previewUrl = useObjectUrl(selectedFile);

  function handleGalleryChange(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0] ?? null;
    setSelectedFile(file);
  }

  function openCamera() {
    setIsCameraOpen(true);
  }

  function openGallery() {
    galleryInputRef.current?.click();
  }

  function clearSelection() {
    setSelectedFile(null);
    if (galleryInputRef.current) galleryInputRef.current.value = "";
    setScanResult(null);
  }

  async function handleScan() {
    setIsScanning(true);

    // BACKEND INTEGRATION START
    // Replace this demo block with a real backend call.
    // Example:
    // 1. send `selectedFile` to your scanner endpoint
    // 2. await the response from the backend
    // 3. store the response in `scanResult`
    // BACKEND INTEGRATION END

    // EXAMPLE SCAN START
    await new Promise((resolve) => setTimeout(resolve, 900));

    if (!selectedFile) {
      setScanResult("Demo scan: no image selected yet. Add a photo first, then connect the backend here.");
    } else {
      setScanResult(
        `Demo scan result for ${selectedFile.name}: likely recyclable plastic/metal packaging. Replace this with your backend response.`
      );
    }
    // EXAMPLE SCAN END

    setIsScanning(false);
  }

  return (
    <div className="flex min-h-screen flex-col bg-white font-sans dark:bg-black">
      <ScannerHeader />

      <ScannerBody
        file={selectedFile}
        previewUrl={previewUrl}
        scanResult={scanResult}
        isScanning={isScanning}
        onOpenCamera={openCamera}
        onOpenGallery={openGallery}
        onClear={clearSelection}
        onScan={handleScan}
      />

      <ScannerFooter />

      <input
        ref={galleryInputRef}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={handleGalleryChange}
      />

      {isCameraOpen && (
        <CameraCaptureModal
          onCapture={(file) => setSelectedFile(file)}
          onClose={() => setIsCameraOpen(false)}
        />
      )}
    </div>
  );
}

"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";

export default function Root() {
  const router = useRouter();

  useEffect(() => {
    // Check if user is logged in by looking for user data in localStorage
    // Wrap in try/catch in case of unexpected errors (e.g. strict cookie policies)
    let handled = false;
    try {
      const userExists = localStorage.getItem("user");

      if (userExists) {
        // User is already logged in, redirect to HomePage
        router.replace("/HomePage");
        handled = true;
      } else {
        // No user logged in, redirect to StartPage
        router.replace("/StartPage");
        handled = true;
      }
    } catch (err) {
      // If anything goes wrong, log to console and fall back to StartPage
      // This prevents the UI from remaining stuck with no action.
      // eslint-disable-next-line no-console
      console.error("Redirect check failed:", err);
      try {
        router.replace("/StartPage");
        handled = true;
      } catch (e) {
        // ignore
      }
    }

    // Safety fallback: if router.replace didn't run (rare), navigate after 2s
    const t = setTimeout(() => {
      if (!handled) {
        // eslint-disable-next-line no-console
        console.warn("Fallback redirect to /StartPage after timeout");
        try {
          router.replace("/StartPage");
        } catch (e) {
          // ignore
        }
      }
    }, 2000);

    return () => clearTimeout(t);
  }, [router]);

  // Show a loading state while redirecting. Provide a visible fallback link
  // so the user can continue if programmatic navigation fails.
  return (
    <div className="flex min-h-screen items-center justify-center bg-white dark:bg-black">
      <div className="flex flex-col items-center gap-4">
        <div className="w-12 h-12 border-4 border-green-200 border-t-green-600 rounded-full animate-spin"></div>
        <p className="text-gray-600 dark:text-gray-400">Loading your account...</p>
        <p className="text-sm text-gray-500 dark:text-gray-400 mt-2">If this takes too long, <a href="/StartPage" className="text-green-600 underline">open the Start page</a>.</p>
      </div>
    </div>
  );
}

